import json
import math
import argparse
import sys
from pathlib import Path
from collections import Counter

BASE = Path("/root/autodl-tmp/pacs")

# Null ii_mid below this fraction is expected (many problems lack mid-phase segments)
MID_NULL_WARN_THRESHOLD = 0.80
# Null ii_high/ii_low above this fraction is an error
HILO_NULL_ERROR_THRESHOLD = 0.10


def load_profiling(dirpath):
    fpath = Path(dirpath) / "profiling_results.json"
    if not fpath.exists():
        return None
    with open(fpath) as f:
        return json.load(f)


def validate_one(dirpath, expected_n=None):
    """Validate a single profiling_results.json.

    Returns (has_errors: bool, errors: list[str], warnings: list[str]).
    """
    errors = []
    warnings = []
    data = load_profiling(dirpath)
    if data is None:
        return True, [f"File not found: {dirpath}/profiling_results.json"], []

    config = data.get("config", {})
    config_n = config.get("n_problems")

    ppi = data.get("per_problem_ii", {})
    if not ppi:
        return True, ["Missing per_problem_ii section"], []

    for sparsity_key, problems in ppi.items():
        prefix = f"[{sparsity_key}]"
        n = len(problems)

        # Problem count
        if expected_n is not None and n != expected_n:
            errors.append(f"{prefix} Expected {expected_n} problems, got {n}")
        if config_n is not None and n != config_n:
            errors.append(f"{prefix} Config says n_problems={config_n}, got {n}")

        # problem_idx monotonicity and uniqueness
        indices = [p.get("problem_idx") for p in problems]
        if None in indices:
            errors.append(f"{prefix} Some entries missing problem_idx")
        else:
            if indices != sorted(indices):
                errors.append(f"{prefix} problem_idx not monotonically increasing")
            dupes = [idx for idx, cnt in Counter(indices).items() if cnt > 1]
            if dupes:
                errors.append(f"{prefix} Duplicate problem_idx: {dupes[:5]}")

        # problem_id uniqueness — key contamination signal
        pids = [p.get("problem_id") for p in problems]
        pid_dupes = [pid for pid, cnt in Counter(pids).items() if cnt > 1]
        if pid_dupes:
            errors.append(f"{prefix} CRITICAL: Duplicate problem_id ({len(pid_dupes)}): {pid_dupes[:3]}...")

        # NaN/Inf/null checks with severity levels
        for field in ["ii_high", "ii_low"]:
            vals = [p.get(field) for p in problems]
            n_none = sum(1 for v in vals if v is None)
            n_nan = sum(1 for v in vals if isinstance(v, float) and math.isnan(v))
            n_inf = sum(1 for v in vals if isinstance(v, float) and math.isinf(v))
            if n_nan > 0:
                errors.append(f"{prefix} {field}: {n_nan} NaN values")
            if n_inf > 0:
                errors.append(f"{prefix} {field}: {n_inf} Inf values")
            if n > 0 and n_none / n > HILO_NULL_ERROR_THRESHOLD:
                errors.append(f"{prefix} {field}: {n_none}/{n} null ({n_none/n:.0%} > {HILO_NULL_ERROR_THRESHOLD:.0%})")
            elif n_none > 0:
                warnings.append(f"{prefix} {field}: {n_none}/{n} null (within tolerance)")

