        if n_nan_mid > 0:
            errors.append(f"{prefix} ii_mid: {n_nan_mid} NaN values")
        if n > 0 and n_none_mid / n > MID_NULL_WARN_THRESHOLD:
            warnings.append(f"{prefix} ii_mid: {n_none_mid}/{n} null ({n_none_mid/n:.0%})")

    return len(errors) > 0, errors, warnings


def validate_cross_condition_alignment(dirs_and_data):
    """Check that paired conditions share the same problem_ids in the same order."""
    issues = []
    pid_sets = {}
    for dirname, data in dirs_and_data.items():
        if data is None:
